pub fn build_enr<E: EthSpec>(
    enr_key: &CombinedKey,
    config: &NetworkConfig,
    enr_fork_id: &EnrForkId,
    custody_group_count: Option<u64>,
    next_fork_digest: [u8; 4],
    spec: &ChainSpec,
