    spec: &ChainSpec,
) -> Result<Enr, String> {
    let mut builder = discv5::enr::Enr::builder();
    let (maybe_ipv4_address, maybe_ipv6_address) = &config.enr_address;

    if let Some(ip) = maybe_ipv4_address { builder.ip4(*ip); }
    if let Some(ip) = maybe_ipv6_address { builder.ip6(*ip); }
    if let Some(udp4_port) = config.enr_udp4_port { builder.udp4(udp4_port.get()); }
    if let Some(udp6_port) = config.enr_udp6_port { builder.udp6(udp6_port.get()); }

    // Add EIP 7636 client information
    if !config.private {
        builder.client_info(client_name().to_string(), version().to_string(), None);
    }

    // QUIC fields (only if libp2p + QUIC both enabled)
    if !config.disable_quic_support {
        if let Some(quic4_port) = config.enr_quic4_port.or_else(|| { ... }) {
            builder.add_value(QUIC_ENR_KEY, &quic4_port.get());
        }
        if let Some(quic6_port) = config.enr_quic6_port.or_else(|| { ... }) {
            builder.add_value(QUIC6_ENR_KEY, &quic6_port.get());
        }
    }

    // TCP ports (fallback to listen port if ENR port not set)
    let tcp4_port = config.enr_tcp4_port.or_else(|| { ... });
    if let Some(tcp4_port) = tcp4_port { builder.tcp4(tcp4_port.get()); }

    let tcp6_port = config.enr_tcp6_port.or_else(|| { ... });
    if let Some(tcp6_port) = tcp6_port { builder.tcp6(tcp6_port.get()); }
